// Stockfish runs in an isolated worker; the UI can terminate it on pause or resignation.
import {botTiming} from './game-core.js';
export function stockfishThinkTime(clock,increment=0){return botTiming(4,clock,increment).budget}
export class StockfishOpponent{
 constructor(){this.onmessage=null;this.onerror=null;this.closed=false;this.ready=false;this.pending=null;this.watchdog=setTimeout(()=>this.fail('Stockfish did not load.'),20000);this.loading=this.load()}
 async load(){try{const encoded=(await Promise.all(Array.from({length:4},async(_,i)=>{const response=await fetch(new URL('./vendor/stockfish/engine-gzip-'+i+'.txt',import.meta.url));if(!response.ok)throw Error('Engine download failed');return response.text()}))).join('');if(this.closed)return;const bytes=Uint8Array.from(atob(encoded.trim()),c=>c.charCodeAt(0));const unpacked=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(this.closed)return;this.wasmURL=URL.createObjectURL(new Blob([unpacked],{type:'application/wasm'}));const engineURL=new URL('./vendor/stockfish/stockfish-19-lite-single.js',import.meta.url);engineURL.hash=encodeURIComponent(this.wasmURL);this.worker=new Worker(engineURL);this.worker.onerror=e=>this.fail(e.message||'Stockfish could not load.');this.worker.onmessage=({data})=>{for(const line of String(data).split('\n'))this.receive(line.trim())};this.worker.postMessage('uci')}catch(e){this.fail(e.message)}}

 fail(message){if(this.closed)return;this.onerror?.({message});this.terminate()}
 receive(line){if(this.closed)return;if(this.pending?.review&&this.reviewLine(line))return;if(line==='uciok'){this.worker.postMessage('setoption name Hash value 32');this.worker.postMessage('setoption name Skill Level value 20');this.worker.postMessage('setoption name UCI_LimitStrength value false');this.worker.postMessage('isready')}else if(line==='readyok'){this.ready=true;clearTimeout(this.watchdog);this.start()}else if(line.startsWith('bestmove ')&&this.pending){const code=line.split(/\s+/)[1],id=this.pending.id;clearTimeout(this.watchdog);this.pending=null;if(!/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(code))return this.fail('Stockfish returned no legal move.');this.onmessage?.({data:{id,move:{from:code.slice(0,2),to:code.slice(2,4),...(code[4]?{promotion:code[4]}:{})}}})}}
 postMessage(data){if(this.closed)return;this.pending=data;if(this.ready)this.start()}
 start(){if(!this.pending||this.closed)return;const d=this.pending;this.worker.postMessage('ucinewgame');const base=d.initialFen?'fen '+d.initialFen:'startpos';this.worker.postMessage(d.history?'position '+base+(d.history.length?' moves '+d.history.join(' '):''):'position fen '+d.fen);this.watchdog=setTimeout(()=>this.fail('Stockfish took too long. Please retry.'),d.thinkMs+10000);this.phase='best';this.metric=null;this.worker.postMessage('go movetime '+d.thinkMs)}
 reviewLine(line){const d=this.pending;if(line.startsWith('info ')){const score=line.match(/score (cp|mate) (-?\d+)/),depth=line.match(/depth (\d+)/);if(score&&!/bound/.test(line))this.metric={type:score[1],value:Number(score[2]),depth:Number(depth?.[1]||0)};return true}if(!line.startsWith('bestmove '))return false;const code=line.split(/\s+/)[1];if(this.phase==='best'){this.bestCode=code;this.bestMetric=this.metric;if(code===d.chosenUci){this.finishReview();return true}this.phase='played';this.metric=null;this.worker.postMessage('position fen '+d.fen);this.worker.postMessage('go searchmoves '+d.chosenUci+' movetime '+d.thinkMs);return true}this.finishReview();return true}
 finishReview(){const d=this.pending,a=this.metric,b=this.bestMetric;clearTimeout(this.watchdog);this.pending=null;if(!a||!b)return this.fail('Position evaluation did not finish. Please retry.');const points=s=>s.type==='mate'?Math.sign(s.value)*(100000-Math.abs(s.value)):s.value;this.onmessage?.({data:{id:d.id,engine:'stockfish',bestCode:this.bestCode,score:points(b),actualScore:points(a),actualMate:a.type==='mate'?a.value:null,loss:Math.max(0,points(b)-points(a)),depth:Math.min(a.depth,b.depth)}})}
 terminate(){if(this.closed)return;this.closed=true;clearTimeout(this.watchdog);this.pending=null;this.worker?.terminate();if(this.wasmURL)URL.revokeObjectURL(this.wasmURL)}
}
